import sys
from collections import Counter

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = [int(x) for x in data[1:n+1]]

    def get_prime_factors(x):
        factors = []
        d = 2
        while d * d <= x:
            while x % d == 0:
                factors.append(d)
                x //= d
            d += 1
        if x > 1:
            factors.append(x)
        return factors

    prime_counts = {}
    total_primes = 0

    for val in a:
        factors = get_prime_factors(val)
        counts = Counter(factors)
        for p, c in counts.items():
            if p not in prime_counts:
                prime_counts[p] = 0
            prime_counts[p] = max(prime_counts[p], c)
        total_primes += len(factors)

    unique_primes = list(prime_counts.keys())
    m = len(unique_primes)

    if m == 0:
        print(0)
        return

    max_count = 0
    for p in unique_primes:
        max_count = max(max_count, prime_counts[p])

    min_leaves = 0
    for p in unique_primes:
        min_leaves += prime_counts[p]

    if max_count == 1:
        ans = min_leaves + (m - 1)
    else:
        ans = min_leaves + (max_count - 1) * m

    print(ans)

solve()
